  AvgDialog_118952_Content_12 = {
    Text = "দেবতা নীরবই রইলেন।"
  },
  AvgDialog_118952_Content_13 = {
    Text = "<color=#E6E6E6>তাঁর আবির্ভাবের পর পঞ্চম দিন।</color>"
  },
  AvgDialog_118952_Content_14 = {
    Text = "মিরিয়াম আমাকে জিজ্ঞেস করেছিল, দেবতার সঙ্গে আমার সাক্ষাতের ফলাফল কী হয়েছিল।"
