  },
  AvgDialog_118952_Content_19 = {
    Text = "মিরিয়াম লেমুরিয়ার অবস্থান সম্পর্কে জানতে চেয়েছিল, আর আমি কেবল অস্পষ্টভাবে উত্তর দিতে পেরেছিলাম; তার অভিব্যক্তি ছিল সংশয়ের।"
  },
  AvgDialog_118952_Content_2 = {
