  AvgDialog_120297_Content_116 = {
    Text = "তুমি মুখ খুলে কিছু বলতে চাও, কিন্তু শব্দগুলো তোমাকে ফাঁকি দেয়; তুমি শুধু ফাঁকা দৃষ্টিতে তার দিকে তাকিয়ে থাকতে পারো। তীক্ষ্ণ, বিদ্ধকারী কানে-শোঁ শোঁ শব্দ তোমার স্নায়ু ছিঁড়ে ফেলে, চারদিকের জগৎকে ডুবিয়ে দেয়। তার হাতের lingering স্পর্শ তোমার পিঠ বেয়ে সরে যায়, তারপর সে ঘুরে দাঁড়ায় এবং আঙিনার দিকে হাঁটা শুরু করে।"
  },
  AvgDialog_120297_Content_117 = {
