  AvgDialog_128700_Content_68 = {
    Text = "ভর্টিস কিছুক্ষণ চুপ করে থাকে। তারপর সে জাহাজের সবচেয়ে বড়, সবচেয়ে নরম কম্বলটা টেনে এনে মেঝেতে পেতে দেয়—একটু দূরত্ব রেখে।"
