  AvgDialog_131201_Content_83 = {
    Text = "আমি যুদ্ধ থামাইনি, গোপনরক্ষক {Male=মহোদয়,Female=মিস} মহাশয়।"
  },
  AvgDialog_131201_Content_84 = {
