  AvgDialog_131201_Content_99 = {
    Text = "তূর্য আর স্যাক্সোফোনের কর্কশ ধ্বনি জানালার বাইরে দিয়ে ভেসে আসে, সঙ্গে করে আনে দূরবর্তী জনতার উল্লাস আর অভিশাপ।"
  },
  AvgDialog_131202_Content_1 = {Text = "পপ—"},
  AvgDialog_131202_Content_10 = {
