  AvgDialog_131206_Content_2 = {
    Text = "প্রাচীন ধোঁয়া, নিদ্রিত"
  },
  AvgDialog_131206_Content_20 = {
    Text = "সহজ গল্প সামলানো সহজতর, হ্যাঁ—কিন্তু কিছু মানুষের জন্য, একটি সহজ গল্প তাদের নিয়তিকে ধারণ করতে পারে না।"
  },
  AvgDialog_131206_Content_21 = {
