  AvgDialog_131206_Content_53 = {
    Text = "মিথাগ? এমন কোনো জায়গার নাম আমরা কখনো শুনিনি, {Male=মহাশয়,Female=মিস}।"
  },
  AvgDialog_131206_Content_54 = {
