  AvgDialog_131208_Content_63 = {
    Text = "সতেরো হাজার বছরের সহনশীলতা... প্রতিটি বিপর্যয় পেরিয়ে টিকে থাকা এক প্রাচীন সভ্যতা, এখন পতনের মুখে..."
