  AvgDialog_131208_Content_70 = {
    Text = "নীরবতায় অশ্রু ঝরে। অ্যারাকনি ম্লান হাসে, জানালার বাইরে তাকিয়ে থাকে। ধ্বংসস্তূপে পরিণত পৃথিবীর মাঝে, কেবল বাইরে দাঁড়িয়ে থাকা ভেঙে পড়া প্রাসাদটিই টিকে আছে।"
