  AvgDialog_131209_Content_42 = {
    Text = "এই মাত্রায়, নেফ্রেয়া আসলে ছিল... আলোবাহকদের গির্জার প্রতিষ্ঠাতা!"
  },
  AvgDialog_131209_Content_43 = {
