  AvgDialog_131209_Content_72 = {Text = "পপ—"},
  AvgDialog_131209_Content_73 = {
    Text = "নেফ্রেয়ার আঙুলের তীক্ষ্ণ টোকায়, ছোট বালিকার দেহ রঙিন রক্তিম আতশবাজির মতো বিস্ফোরিত হয়।"
  },
  AvgDialog_131209_Content_74 = {
    Text = "ল্যান্টার্নের আলো সেই ছিটে ধরা দেয়, প্রাচীরে রক্তলাল এক ফুল আঁকে।"
  },
  AvgDialog_131209_Content_75 = {
