  AvgDialog_131212_Content_25 = {
    Text = "কড়াৎ—"
  },
  AvgDialog_131212_Content_26 = {
    Text = "পরিচারিকার বরফশীতল রক্ত অ্যারাকনির শান্ত মুখে ছিটকে পড়ে, সঙ্গে নিয়ে আসে আইরিস ফুলের সূক্ষ্ম সুগন্ধ।"
  },
  AvgDialog_131212_Content_27 = {
    Text = "আলো আবার মিটমিট করে জ্বলে ওঠে। অ্যারাকনি দেখে তার পরিচারিকার বিচ্ছিন্ন দেহ, আর যে ব্লেড তাকে ভেদ করে চলে গেছে, তা এখনো সামনে ধেয়ে চলেছে। ইস্পাতের পেছনে, পুতুলগুলো ক্ষুধার্ত বন্যপশুর পাল হয়ে তার দিকে উচ্ছ্বাস নিয়ে ঝাঁপিয়ে পড়ছে।"
  },
  AvgDialog_131212_Content_28 = {Text = "..."},
  AvgDialog_131212_Content_29 = {
    Text = "ব্রেক ক্লান্ত ধাতব চিৎকারে গোঙায়। তার সৃষ্ট হাওয়ায় আরেক পরিচারিকার চুল হালকা দুলে ওঠে।"
  },
  AvgDialog_131212_Content_3 = {
