  },
  AvgDialog_131212_Content_37 = {
    Text = "সেই নিষ্প্রভ থিয়েটারে, তারা ছিল অল্প কয়েকটি উজ্জ্বল আত্মার একজন।"
  },
  AvgDialog_131212_Content_38 = {
