  },
  AvgDialog_131212_Content_41 = {
    Text = "<Italic:\"দেখো! আমি ভাগ্যের প্রভু, অনুগত জল্লাদ! আমি ন্যায়ের পথগুলোই বেছে নেব, আর প্রতিটি ভ্রান্তিকে নিক্ষেপ করব অতলে!\">"
  },
  AvgDialog_131212_Content_42 = {
