  AvgDialog_131214_Content_66 = {
    Text = "শেষ হলো, নেফরিয়া।"
  },
  AvgDialog_131214_Content_67 = {
    Text = "একটি তার মৃদু কেঁপে উঠলো। নেফরিয়া একঝাঁক সাদা বকের ডাক শুনতে পেল, ঠিক যেমনটা সে অনেক ছোট, অনেক ছোট থাকতে শুনেছিল, যেদিন তার পিতা তার জন্য মোইরাই নামের সেই চরকাটি নিয়ে এসেছিলেন।"
