  AvgDialog_131215_Content_120 = {
    Text = "আমি ভেবেছি, ভেবেছি, কত দীর্ঘ সময় ধরে... তারপর হঠাৎই বুঝলাম। এটাই সেই সেরা উপহার, যা আমি তোমাকে দিতে পারি, প্রিয় বোন আমার!"
  },
  AvgDialog_131215_Content_121 = {
