  },
  AvgDialog_131215_Content_122 = {
    Text = "নেফ্রেয়া সেই কোমল শব্দগুলো উচ্চারণ করতেই, মাত্রিক ফাটলগুলোর ভেতর কালি-কালো কাদামাটি জমতে থাকে। রেশমি পথের শেষ প্রান্তে, এক মহিমান্বিত স্টেজ উন্মোচিত হয়।"
  },
  AvgDialog_131215_Content_13 = {
