  },
  AvgDialog_131215_Content_15 = {
    Text = "অনেক আগেই আমরা দু’জন আলাদা মানুষ হয়ে গেছি, গোপনরক্ষক {Male=মহোদয়,Female=মিস} মহাশয়।"
  },
  AvgDialog_131215_Content_16 = {
