  AvgDialog_131215_Content_17 = {
    Text = "কোনো বন্দী নিজের নিয়তি দেখতে পায় না, যতক্ষণ না রায় ঘোষণা হয়।"
  },
  AvgDialog_131215_Content_18 = {
    Text = "যদি তুমি জানতে, ওই বাতিল করা নিয়তিগুলো বিলীন না হয়ে অতল কারাগারে নির্বাসিত হবে... তবু কি তুমি তা-ই করতে, অ্যারাকনি?"
