  AvgDialog_131215_Content_20 = {
    Text = "নীরবতা। নীরবতা নাট্যকারের চিরন্তন অভিশাপ। নীরবতা বন্দীর শক্তিহীন আত্মপক্ষসমর্থন। মৃত্যুদণ্ডের মতো সেই নীরবতার মাঝখানে নেফ্রেয়ার উন্মত্ত হাসি ফেটে পড়ল।"
  },
  AvgDialog_131215_Content_21 = {
    Text = "ওহ, তুমি অবশ্যই করতে, বোন। নিয়তিই তোমার ধর্ম; কোনো শর্তই তার চূড়ান্ত উত্তর বদলাতে পারে না।"
  },
  AvgDialog_131215_Content_22 = {
