  },
  AvgDialog_131215_Content_37 = {
    Text = "সুন্দরী নারীটি সুশোভিত ভঙ্গিতে অ্যারাকনি ডলের প্রতি নতজানু হয়।"
  },
  AvgDialog_131215_Content_38 = {
