  },
  AvgDialog_131215_Content_40 = {
    Text = "তুমি শহরের রাস্তায় হাঁটবে, তোমার দয়ায় দৃষ্টিসীমার সবকিছুকে উষ্ণ করবে।"
  },
  AvgDialog_131215_Content_41 = {
