  AvgDialog_131221_Content_17 = {
    Text = "আলাদা হয়ে কাজ করার সময়, আমি কিছু সন্দেহজনক পথচারী দেখেছিলাম। আমি কিছুটা পথ তাদের অনুসরণ করেছি এবং তাদের কথোপকথন শুনেছি।"
  },
  AvgDialog_131221_Content_18 = {
    Text = "তারা এমন কিছু খুঁজছে, যেগুলোকে তারা 「পাপেট」 বলে ডাকে।"
