  AvgDialog_131221_Content_19 = {
    Text = "আমার সন্দেহ, আপনি আগে যে স্টেজের নিয়তির দূষণের কথা বলেছিলেন, তা হয়তো কেবল প্রাথমিক এক ব্যবস্থা মাত্র।"
