  AvgDialog_131221_Content_2 = {
    Text = "বেশ চমৎকার এক দৃশ্য..."
  },
  AvgDialog_131221_Content_20 = {
    Text = "ওই 「পুতুল」 গুলিই তাদের আসল লক্ষ্য।"
