  AvgDialog_131221_Content_21 = {
    Text = "আমার বোন তার এবং তার সেবকদের ভাগ্যের সুতো লুকিয়ে রেখেছে, আমি সহজে তাদের দেখতে পাই না। আপনি অত্যন্ত মূল্যবান একটি তথ্য দিয়েছেন, মিস্টার উইলহেলম।"
  },
  AvgDialog_131221_Content_22 = {
