  AvgDialog_131225_Content_33 = {
    Text = "<Big:<Shake:আআআআহহহ!—>>"
  },
  AvgDialog_131225_Content_34 = {
    Text = "একটা বিদারক চিৎকার কক্ষ জুড়ে প্রতিধ্বনি তোলে। স্মৃতির বয়ামগুলো কেঁপে ওঠে, যেন নীরব, হাস্যোজ্জ্বল দর্শকের জনতা একসাথে খিলখিলিয়ে উঠেছে।"
  },
  AvgDialog_131225_Content_35 = {
