  AvgDialog_131230_Content_17 = {
    Text = "তোমাদের ভাগ্যের সুতো আবার একসাথে জুড়ে গেছে, এর মানে কি…… তোমরা এখন আবার একই সত্তা?"
  },
  AvgDialog_131230_Content_18 = {
