  AvgDialog_131230_Content_19 = {
    Text = "কিন্তু ভাগ্যের জাল একটিই। আপনি যে নেফরিয়াকে চিনতেন, সেই অতল গহ্বরে নিমজ্জিত, ভাগ্য-পরিত্যক্ত প্রতিশোধকারী — এই জালে তার কোনো সুতো নেই।"
  },
  AvgDialog_131230_Content_2 = {
