  },
  AvgDialog_131232_Content_43 = {
    Text = "রোম্যান্স পতনের আগে তাকে বিপদের কথা জানাতে পেরেছিল। এখন সে লুকিয়ে আছে, তোমার এক পুরাতন বন্ধুর আশ্রয়ে।"
  },
  AvgDialog_131232_Content_44 = {
    Text = "একজন পুরাতন বন্ধু...?"
