  AvgDialog_131232_Content_45 = {
    Text = "আমার সঙ্গে আসো, গোপনরক্ষক {Male=মহোদয়,Female=মিস} মহাশয়। লেডি সোরেলের মহা স্যালন শুরু হতে চলেছে।"
  },
  AvgDialog_131232_Content_5 = {
