  AvgDialog_139660_Content_21 = {
    Text = "সে মাথা নিচু করে, ভ্রু কুঁচকে বিড়বিড় করে বলল।"
  },
  AvgDialog_139660_Content_22 = {
    Text = "একজন মানুষ ছিল। অত্যন্ত গুরুত্বপূর্ণ একজন। সেই মানুষটার মুখ……আমার মনে থাকার কথা। নিশ্চয়ই মনে আছে। কিন্তু এখন যখন তার কথা ভাবতে যাই, শুধু দেখতে পাই——"
