  AvgDialog_139660_Content_23 = {
    Text = "——শুধু একটা অবয়ব। যেন একটা ঘোলা কাচের আড়ালে। জানি সে সেখানে আছে, জানি সে খুব গুরুত্বপূর্ণ, কিন্তু সব বিস্তারিত যেন……মুছে ফেলা হয়েছে।"
  },
  AvgDialog_139660_Content_24 = {
    Text = "শুধু সে না। অন্যান্য বিষয়ও একই রকম। আমি জানি আমার কিছু করার আছে——খুব গুরুত্বপূর্ণ কিছু।"
  },
  AvgDialog_139660_Content_25 = {
    Text = "কিন্তু প্রতিটি স্মৃতি একে অপরের সাথে লড়াই করছে। একটি অংশ বলছে সে খুব কোমল ছিল, আর পরের অংশ বলছে আমি অনেকক্ষণ খুব অন্ধকার একটা জায়গায় ছিলাম।"
  },
  AvgDialog_139660_Content_26 = {
