  },
  AvgDialog_139660_Content_27 = {
    Text = "প্রতিটাই সত্যি মনে হয়। কিন্তু একসাথে রাখলে একটা আরেকটার সাথে বিরোধ করে।"
  },
  AvgDialog_139660_Content_28 = {
    Text = "তুমি এই অবস্থা আগে দেখেছ।"
