  },
  AvgDialog_139660_Content_31 = {
    Text = "সায়ার আঙুলগুলো কুঁকড়ে গেল, যেন এমন কিছু আঁকড়ে ধরতে চাইছে যা আর অস্তিত্বে নেই।"
  },
  AvgDialog_139660_Content_32 = {
