  AvgDialog_139662_Content_58 = {
    Text = "এ, কেন?"
  },
  AvgDialog_139662_Content_59 = {
    Text = "উম্... মনে হচ্ছে এখন এটাই করা উচিত।"
  },
  AvgDialog_139662_Content_6 = {
    Text = "জেগে ওঠো, তাড়াতাড়ি জেগে ওঠো……"
  },
  AvgDialog_139662_Content_60 = {
    Text = "কেন, সেটা একটু মনে করতে পারছি না।"
