  AvgDialog_139662_Content_61 = {
    Text = "তার ওপর..."
  },
  AvgDialog_139662_Content_62 = {
    Text = "তরুণীটি মাথা একটু কাত করল, যেন কৌতূহলী হয়ে মৃদু হাসল।"
  },
  AvgDialog_139662_Content_63 = {
    Text = "তুমিও মনে হচ্ছে আমাকে ছুঁতে চাইছ।"
  },
  AvgDialog_139662_Content_64 = {
    Text = "তুমি চাও, অবশ্যই চাও।"
