  AvgDialog_139662_Content_65 = {
    Text = "এতটা পথের অন্ধকার, দুর্গন্ধ, বিরক্তিকর ইন্দ্রিয় আঘাতের পর, তুমি কেন চাইবে না প্রথম জীবন্ত মানুষটিকে স্পর্শ করতে?"
