  AvgDialog_139663_Content_24 = {
    Text = "শুধু তুমি নও, অসংখ্য মানুষ ক্ষয়ের কারণে তাদের গুরুত্বপূর্ণ স্মৃতি হারিয়েছে।"
  },
  AvgDialog_139663_Content_25 = {
