  AvgDialog_139663_Content_7 = {
    Text = "সায়ার দৃষ্টি এদিক-ওদিক ঘুরতে লাগল, কথার শেষাংশ সে গিলে ফেলল।"
  },
  AvgDialog_139663_Content_8 = {
    Text = "যাই হোক, তুমি যে রামোনার কথা বলছ, সেও কি তোমার মতো বিশেষ?"
