  AvgDialog_139663_Content_9 = {
    Text = "সে যদি সাধারণ মানুষ হয়, তাহলে সম্ভবত আমার সাথে যোগাযোগ করতে পারবে না।"
  },
  AvgDialog_141373_Content_1 = {
    Text = "এটা তোমার প্রথমবার এপোয়ান্সে আসা নয়, কিন্তু কোনোবারই এই মুখহীন সত্তাগুলো আজকের মতো এত অস্থিরতায় ছিল না।"
