  AvgDialog_141373_Content_17 = {
    Text = "ঠিক আছে, আমি স্বীকার করছি এটা কিছুটা নিয়মবিরুদ্ধ, কিন্তু চিন্তা করো না, আমি তোমাকে মিথাগে ফিরিয়ে দেব।"
  },
  AvgDialog_141373_Content_18 = {
    Text = "অতল গহ্বর তোমাকে ইতিমধ্যে ঘিরে ফেলেছে, বারবার টলমল করতে করতে তোমার ভঙ্গুর বুদ্ধিমত্তা অপরপক্ষের বলা সমস্ত কিছু বোঝার ক্ষমতা সম্পূর্ণ হারিয়ে ফেলেছে।"
  },
  AvgDialog_141373_Content_19 = {Text = "কী?"},
  AvgDialog_141373_Content_2 = {
