  AvgDialog_145513_Content_18 = {
    Text = "পুরনো কথা বলার আগে, একটু ওয়ার্ম-আপ করা যাক — আমাদের রাগে ফুঁসতে থাকা ছোট্ট প্রতারককে একটু শান্ত করি？"
  },
  AvgDialog_145513_Content_2 = {
