  AvgDialog_18994_Content_17 = {
    Text = "আক্রমণের শিকার তো আমরা—যুদ্ধবিরতি ডাকতে আমাদের কোনো ক্ষতি নেই।"
  },
  AvgDialog_18994_Content_18 = {
    Text = "তবে, আমাকে এই নথির মূল্য যাচাই করতে হবে।\nআপনি কি আমাকে প্রথম পৃষ্ঠাটি পড়ার অনুমতি দেবেন?"
