  },
  AvgDialog_21363_Content_46 = {
    Text = "এবার, আমার চোখের সামনে যা অদৃশ্য হল তা আগের চেয়ে শতগুণ সহস্রগুণ বেশি।"
  },
  AvgDialog_21363_Content_47 = {
