  AvgDialog_21363_Content_69 = {
    Text = "যথেষ্ট দ্রুত হতে হবে, যথেষ্ট দ্রুত।"
  },
  AvgDialog_21363_Content_7 = {
    Text = "যাকুতস্কের মতোই, যদি আমি {Male=তাকে,Female=তাকে} ধরে রাখতে পারতাম, তবে ঝড়ের মধ্যে {Male=সে,Female=সে} আমাদের হতাশা থেকে বাঁচাতে পারত।"
