  },
  AvgDialog_22297_Content_60 = {
    Text = "নারীটি ধপাস করে দ্বার বন্ধ করে দিল। রামোনা যদি তোমাকে টেনে না ধরত, তাহলে বেঁকা নাক নিয়ে আজই স্কুলে ফিরতে হতো।"
