  AvgDialog_22297_Content_79 = {
    Text = "এত দানব দিয়ে ঘেরাও হলে, দেবতা হলেও পালাতে পারবে না।\nওই লোকের কথা আর ভেবো না, আমি তোমাকে ক্যাপ্টেনের কাছে নিয়ে যাচ্ছি, দেখি কীভাবে তোমাকে জাহাজ থেকে নামানো যায়।"
