  AvgDialog_22297_Content_80 = {
    Text = "সে অনেক শক্তিশালী, কিছু হবে না।"
  },
  AvgDialog_22297_Content_81 = {
    Text = "হ্যাঁ হ্যাঁ হ্যাঁ, সে বেঁচে থাকবে। ক্যাপ্টেনের সাথে দেখা হয়ে গেলে তোমাকে তার কাছে নিয়ে যাব।"
