  AvgDialog_22297_Content_87 = {
    Text = "জঘন্য জঘন্য জঘন্য! তুই বিশাল গণ্ডগোল করেছিস! এই মহীয়সীর পুরো পরিকল্পনা তছনছ করে দিয়েছিস! কিছু একটা ভাবতে হবে……"
