  AvgDialog_23847_Content_6 = {
    Text = "অগণিত জ্বলজ্বলে কণা জাহাজের চারপাশে ঘুরপাক খাচ্ছিল, যেন হঠাৎ গ্রীষ্মের বনের কোনো পুকুরে ঢুকে পড়া, যেখানে ব্যাঙের ডাক ওঠানামা করছে ঢাকের তালের মতো... প্রতিটি সাগরচারীর ছিল নিজস্ব স্বতন্ত্র ছাপ।"
  },
  AvgDialog_23847_Content_60 = {
    Text = "দেবমাতা... তার জন্য আমি যে নিয়তি নির্ধারণ করেছি, কোনো নশ্বর দেহই তা এড়াতে পারবে না।"
