  },
  AvgDialog_23847_Content_8 = {
    Text = "অন্ধকারে, কয়েকটি আলোর উৎস তীব্রভাবে ঝলমল করছিল, কিন্তু তাদের পিছু ধাওয়া করা প্রমাণিত হলো নিষ্ফল। সাগরচারীদের উপস্থিতি তোমার মস্তিষ্ককে ঘিরে ধরল লোহার প্রতিবন্ধকের মতো।"
  },
  AvgDialog_23847_Content_9 = {
