  AvgDialog_23854_Content_13 = {
    Text = "পুরো গল্পটা... বোঝানোর জন্য খুব বেশি জটিল। আর এখানে মোটেও নিরাপদ নয়। আগে আমাদের অন্যদের সঙ্গে মিলিত হতে হবে।"
