  AvgDialog_24092_Content_66 = {Text = "..."},
  AvgDialog_24092_Content_67 = {
    Text = "কী হয়েছে?"
  },
  AvgDialog_24092_Content_68 = {
    Text = "হয়তো আমার ভ্রম, কিন্তু মনে হলো বায়ুর ভেতর ভয়েসের ফিসফিসানি শুনেছি।"
  },
  AvgDialog_24092_Content_69 = {
    Text = "এই যে, একদম ঠিক সময়ে। দু’জন বাইরের লোক এখনই ঢুকল。\nওদেরই ধরে ফেলব নাকি? তাহলে আর অন্যদের খুঁজে বেড়ানোর ঝামেলা থাকে না।"
