  AvgDialog_24092_Content_76 = {
    Text = "যন্ত্রণাদায়ক পেইন আপনার কপালে আঘাত করল। আঘাতে আপনার চারপাশের জগৎ ঘুরে উঠল। সুযোগ বুঝে মার্ফি আপনার হাত থেকে ভেদ করে বেরিয়ে গেল, মাথা চেপে ধরে কেবিনের আরও ভেতরের দিকে পালিয়ে গেল।"
  },
  AvgDialog_24092_Content_77 = {
