  AvgDialog_24092_Content_89 = {
    Text = "অবশেষে, সমুদ্রের অন্ধকার চিরে এক কোমল আলো ছুরি চালাল। ফ্যাকাশে নীল এক শক্তি তোমার দিকে হাত বাড়াল—নিরাপদ পথের এক দেবকন্যা তার হাত প্রসারিত করল।"
  },
  AvgDialog_24092_Content_9 = {
