  },
  AvgDialog_45413_Content_49 = {
    Text = "কিন্তু সেদিন তো তুমি ওর কাছে হেরেছিলে। তাহলে \"কখনো না\" বলছ কেন?"
  },
  AvgDialog_45413_Content_5 = {
