  AvgDialog_47169_Content_80 = {
    Text = "আমি একসময় আলকেমি শিখেছিলাম, আর আমার বাবা সবসময় বলতেন আমি নাকি সময় নষ্ট করছি। কিন্তু একজন পরিচারিকার সন্তান হিসেবে, আমি যা-ই করি না কেন, তিনি কখনোই তা মেনে নিতেন না… পরিচারিকা, হ্‌ম্‌।"
