  },
  AvgDialog_47169_Content_96 = {
    Text = "দৈত্যটি ছুরিটা ফেলে দিল, মাস্তুলের গায়ে হেলান দিয়ে চোখ বন্ধ করে বিশ্রামে ডুবে গেল।"
  },
  AvgDialog_47169_Content_97 = {
