  AvgDialog_47170_Content_104 = {Text = "@2@3..."},
  AvgDialog_47170_Content_105 = {
    Text = "ট্যালিস উঠে দাঁড়াল, উত্তেজনায় তার মুখ লাল হয়ে উঠেছে। সে মন্ত্রোচ্চারণ শুরু করল এবং হাত নাড়ল।"
  },
  AvgDialog_47170_Content_106 = {
