  AvgDialog_47172_Content_2 = {
    Text = "কয়েক মাস পরে।"
  },
  AvgDialog_47172_Content_20 = {
    Text = "「হে প্রভু, মিরিয়ামকে ক্ষমা করুন; মাছ-মানুষদের দেখে তার মন সম্পূর্ণ ভয়ে ভেঙে পড়েছে... তাকে ক্ষমা করুন, অনুগ্রহ করে ক্ষমা করুন...」"
