  AvgDialog_47178_Content_74 = {
    Text = "যথেষ্ট প্রতিভা আছে, কিন্তু ভক্তি অপ্রতুল। সে আপনাকে সত্যিকার অর্থে সেবা করতে পারবে না, প্রভু।"
  },
  AvgDialog_47178_Content_75 = {
    Text = "সে নীরব প্রার্থনায় বিশ্বাস করে না, তোমার ওপরও নয়, লেমুরিয়ার ভবিষ্যতের ওপরও নয়। সে বিশ্বাস করে শুধু তার পরিবারে।"
  },
  AvgDialog_47178_Content_76 = {
