  AvgDialog_52003_Content_22 = {Text = "পপ—"},
  AvgDialog_52003_Content_23 = {
    Text = "কোনো একটি শব্দে বিচলিত হয়ে, তিনি সিংহাসন থেকে জেগে উঠলেন। তাঁর জাগরণের সাথে সাথে, সমগ্র শূন্য স্থানটি যেন এক মুহূর্তের জন্য ম্লান হয়ে গেল।"
