  AvgDialog_58330_Content_88 = {Text = "...N."},
  AvgDialog_58330_Content_89 = {
    Text = "এটা আমার এবং অ্যালিস্টেয়ারের একমত মতামত। যদি সেই সত্তা হয়, তাহলে সবকিছুর ব্যাখ্যা পাওয়া যায়।"
  },
  AvgDialog_58330_Content_9 = {
    Text = "তিনি জানালার বাইরে কিছু দেখেছিলেন, তাড়াতাড়ি বাইরে যেতে চেয়েছিলেন?"
