  },
  AvgDialog_58330_Content_91 = {
    Text = "ডোর হাতে ধরা গোলাকার ব্রেন ট্যাংকটা আলতো করে ছুঁয়ে একটা হালকা দীর্ঘশ্বাস ফেলল।"
  },
  AvgDialog_58330_Content_92 = {
