  },
  AvgDialog_58331_Content_24 = {
    Text = "কী তাড়াহুড়ো, আমি তো আগে থেকেই তোমাদের বিদায় দেওয়ার পরিকল্পনা করেছিলাম।"
  },
  AvgDialog_58331_Content_25 = {
