  },
  AvgDialog_58331_Content_26 = {
    Text = "আসলে আমি কখনোই তোমার ভাগ্য পুনর্লিখন করিনি। এত মজার একটা খেলায় প্রতারণা করলে কোনো আনন্দই পাওয়া যায় না।"
  },
  AvgDialog_58331_Content_27 = {
