  AvgDialog_58331_Content_5 = {
    Text = "মনিব আপনার প্রতি কোনো ঘৃণা পোষণ করেন না। তিনি যা করেছেন, তাও আপনারই অনুমতিতে। আমরা কেবল বিশ্বস্তভাবে পান্ডুলিপি অনুসারে কাজ করেছি মাত্র।"
