  AvgDialog_58332_Content_23 = {
    Text = "আমি শুধু বিশ্বস্তভাবে ভাগ্যের ভূমিকা পালন করেছি, তিনি আমাকে যে চরিত্রে অভিনয় করতে চেয়েছিলেন সেটাই করেছি।"
