  AvgDialog_58332_Content_25 = {
    Text = "তুমি চোখের সামনে বিদ্বেষপূর্ণ অথচ কিছুটা চেনা চেনা লাগা গ্রাফিতির দিকে তাকিয়ে হঠাৎ সবকিছু বুঝতে পারলে।"
