  AvgDialog_58332_Content_27 = {
    Text = "তাহলে তুমিও সেই জনের খেয়ালখুশির শিকার হয়েছ। এখন আমরা দুজনেই এখানে আটকে আছি, কিছুই করতে পারছি না……"
  },
  AvgDialog_58332_Content_28 = {
    Text = "শুনতে পেয়েছ? এইমাত্র গুলির শব্দ——তোমার বন্ধু এখনও হাল ছাড়েনি।"
