  },
  AvgDialog_58332_Content_33 = {
    Text = "অনেক দিন পর দেখা, অ্যাপোফিস। এ আমার নতুন এক সঙ্গী, {Male:তার,Female:তার} তোমার সাহায্য দরকার।"
  },
  AvgDialog_58332_Content_34 = {
