  AvgDialog_60346_Content_33 = {
    Text = "হায়, ছোট্টটি..."
  },
  AvgDialog_60346_Content_34 = {
    Text = "আমি অনেক আগেই আমার ক্ষমতা তোমাকে দিয়ে দিয়েছি।\nআমার সবকিছু তোমার কাছে অকপটে উন্মুক্ত।"
