  AvgDialog_60351_Content_27 = {
    Text = "রামোনার শক উপেক্ষা করে তাবিল নিরলসভাবে এগিয়ে যায়। তার ভয়েস প্রতিধ্বনিত হয় এই পরিসরের প্রতিটি কোণ থেকে।"
  },
  AvgDialog_60351_Content_28 = {
