  AvgDialog_60351_Content_60 = {
    Text = "তুই-ই সেই চোর, যে সেদিন তাকে আমাদের কাছ থেকে কেড়ে নিয়েছিলি... আজকে, তোমাদের কেউই এখান থেকে যাবে না!"
