  AvgDialog_60351_Content_61 = {
    Text = "তোমার এই অসম্মান আমি উপেক্ষা করব। শেষ পর্যন্ত, আমি এখনই তোমার সমাপ্তি ঘটানোর ইচ্ছে রাখি না।"
