  AvgDialog_66599_Content_41 = {
    Text = "তাঁর অসংখ্য চোখ খুলে গেছে। তাঁর শক্তির বিরুদ্ধে প্রতিরোধ করো, গেট সিল করে দাও, আর তাঁকে আবার তন্দ্রায় প্রত্যাবর্তন করাও। এটাই একমাত্র পথ।"
