  AvgDialog_6777_Content_15 = {
    Text = "লিলি…… পারবে?"
  },
  AvgDialog_6777_Content_150 = {
    Text = "আমি অপেক্ষা করব। কিন্তু এখন, তোমাকে আমার কথা শুনতে হবে।"
  },
  AvgDialog_6777_Content_16 = {
    Text = "অবশ্যই। লিলি তো অনেক শক্তিশালী। লিলি তাদের রক্ষা করবে, তাই না?"
