  AvgDialog_6777_Content_28 = {
    Text = "তার কণ্ঠস্বর শুনতে বেশ স্থির, বুকে বিশ্ববিদ্যালয়ের ব্যাজ কমিউনিকেটর লাগানো, দেখে মনে হচ্ছে, ইনিই দোর্লের বলা সেই প্রফেসর যিনি মাঠ পর্যায়ে গবেষণা করছেন——এভিস।"
