  AvgDialog_6816_Content_37 = {
    Text = "আমাদের সবচেয়ে খারাপ পরিস্থিতির জন্য প্রস্তুত থাকতে হবে, পাহাড়ের পরিবর্তনের দিকে সর্বদা সতর্ক থাকতে হবে।"
  },
  AvgDialog_6816_Content_38 = {
    Text = "আগে নামার পথ বন্ধ হয়ে গেছে, আগে চূড়ার দিকে যেতে হবে, তারপর নতুন পথ খুঁজতে হবে... আমাদের যত তাড়াতাড়ি সম্ভব পাহাড় থেকে নামতে হবে।"
  },
  AvgDialog_6816_Content_39 = {Text = "..."},
  AvgDialog_6816_Content_4 = {
