  },
  AvgDialog_6816_Content_64 = {
    Text = "সে শিলোর দিকে তাকাল, দৃষ্টিতে আগে কখনো দেখা যায়নি এমন প্রশান্তি আর স্থিরতা।"
  },
  AvgDialog_6816_Content_65 = {
