  AvgDialog_68333_Content_6 = {Text = "...@3!!..."},
  AvgDialog_68333_Content_7 = {
    Text = "অরাজক, নিচু স্বরের গর্জন ধ্বনিত হয়, চারপাশের রিয়েল্ম কেঁপে ওঠে।"
  },
  AvgDialog_68333_Content_8 = {
    Text = "এই ভেঙেচুরে পড়া বিস্তারে এক মহাবিশাল গোলক আকার ধারণ করে।"
