  AvgDialog_71992_Content_57 = {
    Text = "উইঙ্কল... পথজুড়ে তুমি আমাকে ভীষণ সাহায্য করেছ। তোমাকে ঠিকমতো ধন্যবাদ জানানোর সুযোগও পাইনি।"
  },
  AvgDialog_71992_Content_58 = {
