  AvgDialog_71994_Content_4 = {
    Text = "দুঃখের বিষয়, আমাকে নিজ হাতেই এটি সম্পন্ন করতে হচ্ছে... আমি এই আগেই মৃত শহরটিকে..."
  },
  AvgDialog_71994_Content_5 = {
