  AvgDialog_71996_Content_15 = {
    Text = "তুমি যে বিস্ফোরণ ঘটিয়েছ, তার ব্যাপ্তি আমি জানি না, কিন্তু আমি সবসময়ই মূল গবেষণার ফলাফলগুলো খুব যত্ন করে সংরক্ষণ করেছি।"
  },
  AvgDialog_71996_Content_16 = {
