  },
  AvgDialog_71996_Content_17 = {
    Text = "আচ্ছা, কথা যথেষ্ট হয়েছে। এখন সময় ল্যাবরেটরির ধ্বংসাবশেষের পথে থাকা এই সব বাধা সরিয়ে ফেলার।"
  },
  AvgDialog_71996_Content_2 = {
