  AvgDialog_71997_Content_15 = {
    Text = "তুমি তোমার আদিম জগতে মেল্টডাউন·ডল যা করেছিল তা স্মরণ করো, আর সম্মতি জানানো তোমার পক্ষে কঠিন হয়ে ওঠে।"
  },
  AvgDialog_71997_Content_16 = {
