  AvgDialog_71997_Content_6 = {
    Text = "তুমি চারদিকে তাকিয়ে নিশ্চিত হও যে তোমার সঙ্গীরা সম্পূর্ণভাবে অদৃশ্য হয়ে গেছে। যুদ্ধের ক্লান্তি আজ পর্যন্ত যেকোনো সময়ের চেয়ে বেশি ভারী।"
  },
  AvgDialog_71997_Content_7 = {
