  AvgDialog_71998_Content_6 = {
    Text = "দেখছি আমরা একসাথেই চাপা পড়তে যাচ্ছি, মিথাগের কুকুরছানা। খুশি তো? লেজ নাড়ো, তোমার জন্য এ এক বিরল সম্মান।"
