  AvgDialog_71998_Content_7 = {
    Text = "তুমি কিছু বোঝার আগেই, অন্ধকার তোমার দৃষ্টিক্ষেত্র গিলে ফেলে।"
  },
  AvgDialog_71999_Content_1 = {
    Text = "অগৃহীত পথ"
  },
  AvgDialog_71999_Content_10 = {
    Text = "তা নির্ভর করে এই সময়টায় তুমি কী করে কাটিয়েছ তার ওপর।"
  },
  AvgDialog_71999_Content_11 = {
