  AvgDialog_71999_Content_34 = {
    Text = "আর মস্তিষ্কের ভ্যাটগুলো… সেগুলো নকশা করা হয়েছে অমূল্য মস্তিষ্ক আর তার ভেতরে থাকা জ্ঞানকে সঞ্চয় করে রাখার জন্য, নির্বিচার আর বেপরোয়া অপচয়ের স্তুপ জমানোর জন্য নয়।"
  },
  AvgDialog_71999_Content_35 = {
