  AvgDialog_72009_Content_71 = {
    Text = "লড়াইয়ের সময় এসেছে..."
  },
  AvgDialog_72009_Content_72 = {
    Text = "একটি নতুন ভবিষ্যতের জন্য লড়ো।"
  },
  AvgDialog_72009_Content_8 = {
    Text = "তাহলে তুমি এটা পারবে না?"
  },
  AvgDialog_72009_Content_9 = {
    Text = "অবশ্যই পারি। ড্যাফোডিলের ছোট্ট মিথাগ দোকান নিশ্চয়ই তোমার প্রার্থনা পূরণ করবে।"
  },
  AvgDialog_72010_Content_1 = {
    Text = "এই যে, পশ্চিম জেলার লোক, আমি কি বিভ্রম দেখছি নাকি?"
