  AvgDialog_72010_Content_10 = {
    Text = "প্রথমত, অতি স্বল্প সময়ে একটি ভবনের নকশা ও নির্মাণ সম্পন্ন করার সক্ষমতা নির্মাতার প্রকৌশল দক্ষতাকে প্রমাণ করে।"
  },
  AvgDialog_72010_Content_11 = {
    Text = "দ্বিতীয়ত, নির্মাতাকে আমার ল্যাবের গঠন সম্পর্কে ঘনিষ্ঠভাবে অবহিত হতে হবে, দীর্ঘ সময় ধরে এর ভেতরেই বাস করে…"
