  AvgDialog_72010_Content_18 = {
    Text = "আরও একটা কথা তোমাকে অবশ্যই মনে করিয়ে দিতে হবে—"
  },
  AvgDialog_72010_Content_19 = {
    Text = "এই নির্মাতার কাছে আমার পরীক্ষাগারের সব ধ্বংসাত্মক যন্ত্র রয়েছে।"
  },
  AvgDialog_72010_Content_2 = {
    Text = "না... তুমি দেখছ না।"
  },
  AvgDialog_72010_Content_20 = {
    Text = "তার কাছে এগুলোর সবকটিতে একই সর্বোচ্চ স্তরের প্রবেশাধিকারও আছে।"
  },
  AvgDialog_72010_Content_21 = {
    Text = "ঠিক তো?"
  },
  AvgDialog_72010_Content_22 = {
    Text = "করিডরের শেষে, অন্যটির অনুরূপ একটি অবয়ব ধীরে ধীরে বেরিয়ে আসে। দু’জন সমগ্র পরীক্ষাগার জুড়ে একে অপরের দিকে তাকিয়ে থাকে, যেন এক বিশাল প্রতিবিম্বের আয়নায় মুখোমুখি প্রতিফলন।"
  },
  AvgDialog_72010_Content_23 = {
    Text = "「অন্য」 মেল্টডাউন·ডল।"
