  AvgDialog_72011_Content_2 = {
    Text = "চোখের সামনে যা দেখা দিচ্ছে, তা একই সঙ্গে অচেনা, আবার অদ্ভুতভাবে পরিচিতও লাগে।"
  },
  AvgDialog_72011_Content_20 = {Text = "..."},
  AvgDialog_72011_Content_21 = {Text = "..."},
  AvgDialog_72011_Content_22 = {
    Text = "তো, জেনকিন, তুমি সত্যিই তৃতীয় কাউকে দেখোনি? ছোট লাল চুলের, খুব চঞ্চল এক গবেষককে..."
