  AvgDialog_72011_Content_24 = {
    Text = "হুড পরা বালিকা উদাসীন ভঙ্গিতে কাঁধ ঝাঁকায়।"
  },
  AvgDialog_72011_Content_25 = {
    Text = "আমি তোমাদের দুই পশ্চিম জেলার লোককে পাথরের স্তুপের ভেতর থেকে খুঁড়ে তুলেছি। ওটাকে আর ধ্বংসাবশেষও বলা যায় না।"
