  AvgDialog_72012_Content_29 = {
    Text = "সারাহ তার সমস্ত পাশবিক শক্তি জড়ো করে টলমল করতে করতে ডেস্কের দিকে এগোয়। তার দেহ দুলে ওঠে, আর সে ডেস্কের গায়ে হেলে পড়ে হাঁপাতে হাঁপাতে শ্বাস সামলানোর চেষ্টা করে।"
  },
  AvgDialog_72012_Content_3 = {
