  AvgDialog_78941_Content_67 = {
    Text = "আরেকটি শিশুকে পড়ে যেতে দেখেই, করপোস্যান্ট পতাকা তুলে চেপে আসা জনতাকে ব্লক করে, আর তুমি সেই সুযোগে শিশুটিকে বাঁচিয়ে নাও।"
