  AvgDialog_89069_Content_1 = {
    Text = "খক... খক..."
  },
  AvgDialog_89069_Content_10 = {
    Text = "আমি ইতিমধ্যে এখান থেকে বার্তা পাঠিয়ে দিয়েছি। খুব শিগগিরই, তারা আমার স্ত্রীকে পুনরুজ্জীবন দেবে..."
