  },
  AvgDialog_89087_Content_22 = {
    Text = "এই রাজ্য বহু বছর ধরে শান্তিতে সমৃদ্ধ হয়েছে, আর আমাদের দক্ষতা শুধু রান্না আর নাচের মধ্যেই সীমাবদ্ধ নয়।"
  },
  AvgDialog_89087_Content_23 = {
