  AvgDialog_89087_Content_34 = {
    Text = "সুরের গতি বাড়তেই ডোরেসেইনের মসৃণ পদক্ষেপ হঠাৎ ধারালো হয়ে ওঠে—তার পা তোমার পায়ে গেঁথে যায়, তোমাকে টেনে নিয়ে যায় পেছনের সমাধিফলকের ফাঁকে।"
  },
  AvgDialog_89087_Content_35 = {
