  AvgDialog_90536_Content_64 = {
    Text = "ওহ, আমি প্রায় ভুলেই গিয়েছিলাম যে আমাদের দিভুস ক্যাস্টর তো আগেই বেশ... ক্ষতিগ্রস্ত।"
  },
  AvgDialog_90536_Content_65 = {
