  AvgDialog_90536_Content_79 = {
    Text = "(সে লম্বা হয়েছে আর মনে হচ্ছে কিছুটা শুকিয়েও গেছে; সৌভাগ্যবশত, আর কোনো ক্ষত নেই, আছে শুধু সেই সুন্দর ডানার জোড়া...)"
