  AvgDialog_90539_Content_61 = {
    Text = "রূপান্তর আচার অনুষ্ঠানের প্রভাব অত্যন্ত ভালো, আমাদের দিকনির্দেশ স্পষ্ট; আজ থেকে প্রতি সপ্তাহে দিভুস পলাক্সের জন্য একবার করে রূপান্তর আচার অনুষ্ঠান সম্পন্ন করো, যত দ্রুত সম্ভব 「পবিত্র হৃদয়」 সম্পন্ন করার জন্য চেষ্টা করো।"
