  AvgDialog_90540_Content_68 = {Text = "..."},
  AvgDialog_90540_Content_69 = {
    Text = "যেই পলাক্সের টলমল পদধ্বনি ভেসে উঠত, ক্যাস্টর উৎকণ্ঠায় তার দিকে ছুটে যেত।"
  },
  AvgDialog_90540_Content_7 = {
    Text = "কিশোর পলাক্স গুদামের কাঠের তাকের ওপর দাঁড়িয়ে, পায়ের আঙুলের ভর রেখে, তার এখনও অপরিণত ডানা ঝাপটানো পাখাগুলো পেছনে কাঁপছিল। শেষমেশ, সে সর্বশক্তি দিয়ে লাফিয়ে উঠে তাক থেকে একটা মোটা হার্ডকভার বই টেনে নামাল।"
  },
  AvgDialog_90540_Content_70 = {
