  AvgDialog_97275_Content_24 = {Text = "..."},
  AvgDialog_97275_Content_25 = {
    Text = "তুমি চোখ বুজে গভীর শ্বাস নাও। হৃদয়ের গভীরে পুঁতে রাখা যন্ত্রণা আর দুঃখ আবারও উচ্ছ্বাস হয়ে ওঠে, আর এবার তার সঙ্গে জুড়ে যায় আতঙ্ক, আত্মসংশয়, আর ভবিষ্যৎ সম্পর্কে অনিশ্চয়তা…"
  },
  AvgDialog_97275_Content_26 = {
